PRAGMA foreign_keys=OFF;
CREATE TABLE "new_User" ("id" TEXT NOT NULL PRIMARY KEY,"username" TEXT NOT NULL,"mobile" TEXT,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"jobTitle" TEXT NOT NULL DEFAULT 'کاربر سامانه',"roleKey" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL);
INSERT INTO "new_User" ("id","username","mobile","passwordHash","name","jobTitle","roleKey","active","createdAt","updatedAt") SELECT "id","username","mobile","passwordHash","name","کاربر سامانه","roleKey","active","createdAt","updatedAt" FROM "User";
DROP TABLE "User"; ALTER TABLE "new_User" RENAME TO "User";
CREATE UNIQUE INDEX "User_username_key" ON "User"("username"); CREATE INDEX "User_mobile_idx" ON "User"("mobile"); CREATE INDEX "User_roleKey_active_idx" ON "User"("roleKey","active");
CREATE TABLE "new_Request" ("id" TEXT NOT NULL PRIMARY KEY,"project" TEXT NOT NULL,"supplier" TEXT NOT NULL,"invoice" TEXT,"requestNumber" TEXT NOT NULL,"date" DATETIME NOT NULL,"department" TEXT NOT NULL,"purchaseType" TEXT NOT NULL,"description" TEXT,"amount" INTEGER NOT NULL,"status" TEXT NOT NULL,"statusType" TEXT NOT NULL,"currentStage" TEXT NOT NULL DEFAULT 'DRAFT',"priority" TEXT NOT NULL DEFAULT 'NORMAL',"createdById" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" DATETIME NOT NULL,CONSTRAINT "Request_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
INSERT INTO "new_Request" ("id","project","supplier","invoice","requestNumber","date","department","purchaseType","description","amount","status","statusType","currentStage","priority","createdById","createdAt","updatedAt") SELECT "id","project","supplier","invoice","requestNumber","date","department","purchaseType","description","amount",CASE "status" WHEN 'در انتظار بررسی' THEN 'PENDING_FIRST_REVIEW' WHEN 'در انتظار پرداخت' THEN 'PENDING_PAYMENT' WHEN 'در انتظار کنترل پرداخت' THEN 'PENDING_PAYMENT_VERIFICATION' WHEN 'در بررسی نهایی' THEN 'PENDING_FINAL_REVIEW' WHEN 'در انتظار تأیید نهایی' THEN 'PENDING_FINAL_APPROVAL' WHEN 'تکمیل‌شده' THEN 'COMPLETED' WHEN 'برگشت‌خورده' THEN 'REJECTED' WHEN 'پیش‌نویس' THEN 'DRAFT' ELSE "status" END,"statusType",CASE "status" WHEN 'در انتظار بررسی' THEN 'FIRST_REVIEW' WHEN 'در انتظار پرداخت' THEN 'PAYMENT' WHEN 'در انتظار کنترل پرداخت' THEN 'PAYMENT_VERIFICATION' WHEN 'در بررسی نهایی' THEN 'FINAL_REVIEW' WHEN 'در انتظار تأیید نهایی' THEN 'FINAL_APPROVAL' WHEN 'تکمیل‌شده' THEN 'COMPLETED' WHEN 'برگشت‌خورده' THEN 'DRAFT' ELSE 'DRAFT' END,"priority","createdById","createdAt","updatedAt" FROM "Request";
DROP TABLE "Request"; ALTER TABLE "new_Request" RENAME TO "Request";
CREATE UNIQUE INDEX "Request_requestNumber_key" ON "Request"("requestNumber"); CREATE INDEX "Request_status_idx" ON "Request"("status"); CREATE INDEX "Request_currentStage_idx" ON "Request"("currentStage"); CREATE INDEX "Request_createdById_idx" ON "Request"("createdById"); CREATE INDEX "Request_date_idx" ON "Request"("date");
ALTER TABLE "Approval" ADD COLUMN "returnTarget" TEXT; CREATE INDEX "Task_requestId_completed_idx" ON "Task"("requestId","completed");
PRAGMA foreign_keys=ON;
